/* Universo SPARK · Contenido del 3.º trimestre de 5.º de primaria, según el Programa Sintético de la Fase 5 (SEP).
   En cada pregunta, la primera opción es la correcta. */
var Fr=(a,b)=>`<span class="fr" role="img" aria-label="${a} sobre ${b}"><i>${a}</i><i>${b}</i></span>`;
const T3_MUNDOS=[];
T3_MUNDOS.push({name:'Ciencias',sub:'Pensamiento científico',lead:'Materiales, imanes, electricidad, calor y planetas: la física y la química de todos los días.',temas:[
{t:'Dureza, flexibilidad y permeabilidad',c:'Propiedades de los materiales',e:[
'Los materiales tienen <b>propiedades</b> que los hacen útiles para distintas cosas. La <b>dureza</b> es la resistencia a ser rayado: el diamante es el material natural más duro y el gis es blando.',
'La <b>flexibilidad</b> es la capacidad de doblarse sin romperse: una liga o una regla de plástico son flexibles; un vidrio no. La <b>permeabilidad</b> es dejar pasar el agua: una esponja y la tela de algodón son permeables; un impermeable de plástico no.',
'Elegimos los materiales según lo que necesitamos: las botas de lluvia deben ser <b>impermeables</b>, las ollas resistentes al calor y los cables flexibles.'],
x:['Un clavo de acero raya la madera porque es más duro.','Una manguera de hule es flexible; un tubo de cobre lo es mucho menos.'],
k:'Dureza: resistir rayones. Flexibilidad: doblarse sin romperse. Permeabilidad: dejar pasar el agua.',
q:[{s:'¿Qué es la dureza?',o:['La resistencia a ser rayado','La capacidad de doblarse','Dejar pasar el agua'],y:'El diamante es muy duro.',p:'Piensa en rayar.'},
{s:'¿Cuál material es permeable?',o:['Una esponja','Una bolsa de plástico','Un vidrio'],y:'Deja pasar el agua.',p:'Absorbe agua.'},
{s:'¿Cuál material es flexible?',o:['Una liga','Un vidrio','Un ladrillo'],y:'Se dobla sin romperse.',p:'Se estira y dobla.'},
{s:'¿Qué propiedad debe tener un impermeable?',o:['No dejar pasar el agua','Ser muy duro','Romperse fácil'],y:'Im-permeable: no permeable.',p:'Im- significa no.'}],
v:[{s:'El diamante es el material natural más duro.',v:true,y:'Puede rayar casi cualquier otro material.'},
{s:'El vidrio es muy flexible.',v:false,y:'Se rompe en lugar de doblarse.'}],
ex:[{s:'¿Por qué los cables eléctricos de casa deben ser flexibles?',o:['Para doblarlos sin que se rompan','Para que dejen pasar el agua','Para rayar las paredes'],y:'Se acomodan por las paredes.'},
{s:'Si un material A raya a un material B, ¿cuál es más duro?',o:['A','B','Son iguales'],y:'El más duro raya al más blando.'}]},

{t:'El aire es un gas',c:'El aire es un gas',e:[
'Aunque no lo veas, el <b>aire</b> es materia: ocupa un lugar, tiene masa y se puede comprimir. Es una <b>mezcla de gases</b>, sobre todo <b>nitrógeno</b> (casi 78 %) y <b>oxígeno</b> (casi 21 %), con un poco de dióxido de carbono, vapor de agua y otros gases.',
'Los gases no tienen forma ni volumen fijos: <b>ocupan todo el espacio</b> del recipiente donde están. Por eso el aire llena un globo y toma su forma.',
'El aire también <b>empuja</b>: esa fuerza se llama <b>presión atmosférica</b>. Al soplar un globo, el aire de adentro empuja las paredes; con el viento, el aire en movimiento mueve las hojas y los papalotes.'],
x:['Si metes un vaso boca abajo en una tina con agua, el agua no entra hasta arriba porque el aire ocupa ese lugar.','Una llanta de bicicleta se infla al meter aire a presión.'],
k:'El aire es una mezcla de gases que ocupa espacio, tiene masa y ejerce presión.',
q:[{s:'¿Qué gas abunda más en el aire?',o:['Nitrógeno','Oxígeno','Dióxido de carbono'],y:'Casi el 78 % del aire.',p:'No es el que respiras para vivir.'},
{s:'¿Qué hacen los gases en un recipiente?',o:['Ocupan todo el espacio','Se quedan en el fondo','Desaparecen'],y:'No tienen forma ni volumen fijos.',p:'Llenan todo.'},
{s:'¿Por qué el agua no entra hasta el fondo de un vaso boca abajo?',o:['Porque el aire ocupa ese lugar','Porque el vaso es mágico','Porque el agua está fría'],y:'El aire ocupa espacio.',p:'¿Qué hay dentro del vaso?'},
{s:'¿Cómo se llama la fuerza con que el aire empuja?',o:['Presión atmosférica','Gravedad','Magnetismo'],y:'Actúa sobre todo lo que nos rodea.',p:'Presión del aire.'}],
v:[{s:'El aire tiene masa.',v:true,y:'Un balón inflado pesa un poco más que uno desinflado.'},
{s:'El aire está hecho solo de oxígeno.',v:false,y:'Es una mezcla; el nitrógeno es el más abundante.'}],
ex:[{s:'¿Qué porcentaje aproximado del aire es oxígeno?',o:['21 %','78 %','100 %'],y:'El resto es casi todo nitrógeno.'},
{s:'¿Qué propiedad del aire permite inflar una llanta?',o:['Se puede comprimir','Es líquido','Es sólido'],y:'Cabe mucho aire en poco espacio.'}]},

{t:'Cocción y descomposición: cambios permanentes',c:'Cambios permanentes',e:[
'Algunos cambios se pueden revertir: el hielo se derrite y el agua se vuelve a congelar. Son <b>cambios temporales</b> o físicos. Otros no tienen marcha atrás: son <b>cambios permanentes</b>, porque se forman <b>sustancias nuevas</b>.',
'La <b>cocción</b> es un cambio permanente: un huevo cocido no vuelve a ser crudo; la masa del pan se convierte en pan. La <b>descomposición</b> también: una fruta se pudre por la acción de hongos y bacterias, y no vuelve a estar fresca.',
'Señales de un cambio permanente: cambio de <b>color</b>, de <b>olor</b>, aparición de <b>burbujas</b> o gas, y liberación de calor o luz. La <b>combustión</b> (quemar) y la <b>oxidación</b> (como el clavo que se oxida) son otros ejemplos.'],
x:['Una manzana partida se pone café porque se oxida.','La composta aprovecha la descomposición para convertir restos de comida en abono.'],
k:'Los cambios permanentes forman sustancias nuevas y no se pueden revertir: cocción, descomposición, combustión.',
q:[{s:'¿Cuál es un cambio permanente?',o:['Cocer un huevo','Derretir hielo','Doblar un papel'],y:'El huevo no vuelve a estar crudo.',p:'No se puede deshacer.'},
{s:'¿Qué produce la descomposición de una fruta?',o:['Hongos y bacterias','El viento','Los imanes'],y:'Son microorganismos descomponedores.',p:'Seres vivos muy pequeños.'},
{s:'¿Cuál es una señal de cambio permanente?',o:['Cambio de color y olor','Cambio de lugar','Cambio de forma al doblarlo'],y:'Indica que hay sustancias nuevas.',p:'Algo nuevo se formó.'},
{s:'¿Por qué se pone café una manzana partida?',o:['Porque se oxida','Porque se congela','Porque se derrite'],y:'Reacciona con el oxígeno del aire.',p:'Reacciona con el aire.'}],
v:[{s:'Derretir hielo es un cambio permanente.',v:false,y:'Es temporal: el agua se puede volver a congelar.'},
{s:'La composta aprovecha la descomposición.',v:true,y:'Convierte restos orgánicos en abono.'}],
ex:[{s:'¿Qué diferencia a un cambio permanente de uno temporal?',o:['En el permanente se forman sustancias nuevas','En el permanente nada cambia','No hay diferencia'],y:'Por eso no se puede revertir.'},
{s:'Quemar papel es un ejemplo de:',o:['Combustión, un cambio permanente','Cambio temporal','Mezcla'],y:'El papel se vuelve ceniza y gases.'}]},

{t:'Imanes: polos, atracción y repulsión',c:'Imanes',e:[
'Un <b>imán</b> atrae objetos de <b>hierro</b>, <b>níquel</b> y <b>cobalto</b>, como clips y clavos. No atrae plástico, madera, vidrio ni la mayoría de las monedas de aluminio o cobre.',
'Todo imán tiene dos <b>polos</b>: <b>norte</b> y <b>sur</b>. Su fuerza es mayor en los polos. Si acercas polos <b>distintos</b> (norte con sur), se <b>atraen</b>; si acercas polos <b>iguales</b>, se <b>repelen</b> (se empujan).',
'La Tierra se comporta como un imán gigante. Por eso la aguja de una <b>brújula</b>, que es un imán pequeño, siempre apunta hacia el norte y sirve para orientarse.'],
x:['Los imanes del refrigerador se pegan porque la puerta tiene hierro.','Si intentas juntar dos imanes por el mismo polo, sientes que se empujan.'],
k:'Los imanes atraen hierro; polos distintos se atraen y polos iguales se repelen.',
q:[{s:'¿Qué objeto atrae un imán?',o:['Un clip de hierro','Un lápiz de madera','Un vaso de vidrio'],y:'El imán atrae el hierro.',p:'Está hecho de metal con hierro.'},
{s:'¿Qué pasa si acercas el polo norte de un imán al polo sur de otro?',o:['Se atraen','Se repelen','No pasa nada'],y:'Polos distintos se atraen.',p:'Distintos se juntan.'},
{s:'¿Qué pasa con dos polos iguales?',o:['Se repelen','Se atraen','Se derriten'],y:'Se empujan entre sí.',p:'Iguales se empujan.'},
{s:'¿Por qué la brújula apunta al norte?',o:['Porque la Tierra se comporta como un imán','Porque el viento la mueve','Porque está pintada'],y:'La aguja es un pequeño imán.',p:'La Tierra es como un imán gigante.'}],
v:[{s:'La fuerza de un imán es mayor en sus polos.',v:true,y:'Ahí se concentra la atracción.'},
{s:'Los imanes atraen todos los metales.',v:false,y:'No atraen aluminio, cobre ni oro, por ejemplo.'}],
ex:[{s:'¿Cuántos polos tiene un imán?',o:['Dos','Uno','Cuatro'],y:'Norte y sur.'},
{s:'¿Para qué sirve una brújula?',o:['Para orientarse','Para medir la temperatura','Para pesar objetos'],y:'Su aguja señala el norte.'}]},

{t:'La gravedad y la caída de los objetos',c:'Gravedad',e:[
'La <b>gravedad</b> es la fuerza con la que la Tierra atrae a todos los objetos hacia su centro. Por eso, al soltar una pelota, cae al suelo, y por eso no salimos flotando.',
'El <b>peso</b> de un objeto es la fuerza con que la gravedad lo atrae. En la Luna, donde la gravedad es unas seis veces menor, pesarías mucho menos, aunque tu <b>masa</b> (la cantidad de materia) sería la misma.',
'Si no hubiera aire, una pluma y una piedra caerían al mismo tiempo. En la Tierra, la pluma cae más despacio porque el <b>aire</b> la frena. Los paracaídas aprovechan esa resistencia del aire.'],
x:['Un astronauta en la Luna puede saltar mucho más alto que en la Tierra.','Una hoja de papel extendida cae despacio, pero hecha bolita cae rápido.'],
k:'La gravedad atrae los objetos hacia la Tierra; el aire frena su caída.',
q:[{s:'¿Qué es la gravedad?',o:['La fuerza con que la Tierra atrae los objetos','La fuerza de un imán','El viento'],y:'Atrae todo hacia el centro de la Tierra.',p:'Hace que las cosas caigan.'},
{s:'¿Por qué una pluma cae más despacio que una piedra?',o:['Porque el aire la frena','Porque no tiene masa','Porque la Tierra no la atrae'],y:'Sin aire caerían igual.',p:'Algo la detiene en el camino.'},
{s:'¿Qué cambia si viajas a la Luna?',o:['Tu peso','Tu masa','Tu estatura'],y:'La masa sigue igual; el peso es menor.',p:'La fuerza con que te atrae.'},
{s:'¿Para qué sirve un paracaídas?',o:['Para que el aire frene la caída','Para caer más rápido','Para flotar en el agua'],y:'Aprovecha la resistencia del aire.',p:'Aprovecha el aire.'}],
v:[{s:'Sin aire, una pluma y una piedra caerían al mismo tiempo.',v:true,y:'Así lo comprobaron astronautas en la Luna.'},
{s:'En la Luna tu masa sería seis veces menor.',v:false,y:'Tu masa es la misma; tu peso es menor.'}],
ex:[{s:'¿Qué es el peso de un objeto?',o:['La fuerza con que la gravedad lo atrae','Su tamaño','Su color'],y:'Depende de la gravedad del lugar.'},
{s:'¿Qué papel cae más rápido?',o:['El hecho bolita','El extendido','Caen igual siempre'],y:'Tiene menos resistencia del aire.'}]},

{t:'El calor: conducción y convección',c:'Conducción y convección',e:[
'El <b>calor</b> es energía que pasa de un cuerpo caliente a uno más frío. Puede viajar de varias formas.',
'En la <b>conducción</b>, el calor pasa por <b>contacto</b>, de partícula en partícula, sobre todo en los sólidos. Una cuchara de metal en una sopa caliente se calienta hasta el mango. Los metales son buenos <b>conductores</b>; la madera, el plástico y el aire son <b>aislantes</b>.',
'En la <b>convección</b>, el calor viaja con el <b>movimiento</b> de líquidos o gases: lo caliente sube y lo frío baja, formando corrientes. Así se calienta el agua de una olla y así se forman los vientos. También existe la <b>radiación</b>: el calor del Sol llega por el espacio sin tocar nada.'],
x:['Las ollas tienen mangos de plástico o madera para no quemarte: son aislantes.','El humo y el aire caliente suben; por eso arriba de un cuarto hace más calor.'],
k:'Conducción: calor por contacto. Convección: calor que viaja con líquidos o gases en movimiento.',
q:[{s:'¿Cómo viaja el calor por conducción?',o:['Por contacto','Por el movimiento del aire','Por la luz del Sol'],y:'De partícula en partícula.',p:'Tocándose.'},
{s:'¿Cuál es buen conductor del calor?',o:['El metal','La madera','El plástico'],y:'Por eso las ollas son de metal.',p:'Las ollas están hechas de él.'},
{s:'¿Qué pasa en la convección?',o:['Lo caliente sube y lo frío baja','El calor pasa por contacto','El calor desaparece'],y:'Se forman corrientes.',p:'Movimiento de líquidos o gases.'},
{s:'¿Por qué los mangos de las ollas son de plástico o madera?',o:['Porque son aislantes','Porque son conductores','Porque son más bonitos'],y:'No dejan pasar el calor fácilmente.',p:'Para no quemarte.'}],
v:[{s:'El calor pasa del cuerpo caliente al frío.',v:true,y:'Nunca al revés por sí solo.'},
{s:'El calor del Sol llega a la Tierra por conducción.',v:false,y:'Llega por radiación, a través del espacio.'}],
ex:[{s:'Una cuchara de metal se calienta en la sopa. ¿Qué forma de transmisión es?',o:['Conducción','Convección','Radiación'],y:'El calor viaja por el metal.'},
{s:'¿Cómo se calienta el agua de una olla de abajo hacia arriba?',o:['Por convección','Por magnetismo','Por gravedad solamente'],y:'El agua caliente sube y la fría baja.'}]},

{t:'Cargas eléctricas, conductores y aislantes',c:'Electricidad',e:[
'Toda la materia tiene <b>cargas eléctricas</b>: <b>positivas</b> y <b>negativas</b>. Las cargas iguales se repelen y las distintas se atraen, como los polos de un imán.',
'Si frotas un globo en tu cabello, el globo gana cargas negativas y puede atraer papelitos o pegarse a la pared: eso es <b>electricidad estática</b>. Los rayos son una descarga enorme de electricidad estática.',
'La <b>corriente eléctrica</b> es el movimiento de cargas por un material. Los <b>conductores</b>, como el cobre y otros metales, la dejan pasar; por eso los cables son de cobre. Los <b>aislantes</b>, como el plástico, el hule y la madera seca, no la dejan pasar; por eso cubren los cables. El agua con sales conduce electricidad: nunca toques aparatos con las manos mojadas.'],
x:['Al quitarte un suéter en un día seco escuchas chasquidos: es electricidad estática.','Los electricistas usan guantes de hule porque es aislante.'],
k:'Cargas iguales se repelen y distintas se atraen; los conductores dejan pasar la corriente y los aislantes no.',
q:[{s:'¿Qué pasa con dos cargas iguales?',o:['Se repelen','Se atraen','Se convierten en luz'],y:'Igual que los polos iguales de un imán.',p:'Como los imanes.'},
{s:'¿Por qué los cables son de cobre?',o:['Porque el cobre es buen conductor','Porque es aislante','Porque es barato y no sirve'],y:'Deja pasar la corriente.',p:'Deja pasar la electricidad.'},
{s:'¿Cuál es un aislante eléctrico?',o:['El hule','El cobre','El hierro'],y:'Por eso los guantes de electricista son de hule.',p:'Cubre los cables.'},
{s:'Un globo frotado atrae papelitos. ¿Qué es?',o:['Electricidad estática','Magnetismo de la Tierra','Gravedad'],y:'El globo quedó con carga.',p:'Se produce al frotar.'}],
v:[{s:'Es seguro tocar aparatos eléctricos con las manos mojadas.',v:false,y:'El agua puede conducir electricidad y causar un choque.'},
{s:'Los rayos son descargas de electricidad estática.',v:true,y:'Se acumula carga en las nubes.'}],
ex:[{s:'¿Qué es la corriente eléctrica?',o:['El movimiento de cargas por un material','Un tipo de viento','Una fuerza de gravedad'],y:'Viaja por los conductores.'},
{s:'¿Para qué se cubren los cables con plástico?',o:['Porque es aislante y evita choques eléctricos','Para que conduzcan mejor','Para que pesen más'],y:'El plástico no deja pasar la corriente.'}]},

{t:'El Sistema Solar: Sol, planetas, lunas y asteroides',c:'Sistema Solar',e:[
'El <b>Sistema Solar</b> está formado por el <b>Sol</b>, una estrella, y todo lo que gira a su alrededor por la gravedad: ocho <b>planetas</b>, sus <b>lunas</b>, <b>planetas enanos</b> como Plutón, <b>asteroides</b> y <b>cometas</b>.',
'En orden desde el Sol, los planetas son: <b>Mercurio, Venus, Tierra, Marte</b> (rocosos y pequeños), y <b>Júpiter, Saturno, Urano y Neptuno</b> (gigantes gaseosos o helados). Júpiter es el más grande; Mercurio, el más pequeño y cercano al Sol.',
'Entre Marte y Júpiter está el <b>cinturón de asteroides</b>, con millones de rocas. Las <b>lunas</b> o satélites giran alrededor de los planetas: la Tierra tiene una; Júpiter y Saturno tienen muchísimas, más de 90 cada uno.'],
x:['Una forma de recordar el orden: «Mi Vieja Tía Marta Jamás Supo Usar Nada».','Saturno es famoso por sus anillos de hielo y roca.'],
k:'El Sol y ocho planetas, con lunas, asteroides y cometas, forman el Sistema Solar.',
q:[{s:'¿Qué es el Sol?',o:['Una estrella','Un planeta','Una luna'],y:'Es el centro del Sistema Solar.',p:'Produce su propia luz.'},
{s:'¿Cuál es el planeta más grande?',o:['Júpiter','La Tierra','Mercurio'],y:'Es un gigante gaseoso.',p:'El quinto planeta.'},
{s:'¿Dónde está el cinturón de asteroides?',o:['Entre Marte y Júpiter','Entre la Tierra y la Luna','Después de Neptuno'],y:'Tiene millones de rocas.',p:'Separa los planetas rocosos de los gigantes.'},
{s:'¿Cuántos planetas tiene el Sistema Solar?',o:['Ocho','Nueve','Doce'],y:'Plutón es un planeta enano.',p:'Plutón ya no cuenta.'}],
v:[{s:'Mercurio es el planeta más cercano al Sol.',v:true,y:'Es también el más pequeño.'},
{s:'La Tierra tiene tres lunas.',v:false,y:'Tiene una sola luna.'}],
ex:[{s:'¿Qué planeta es famoso por sus anillos?',o:['Saturno','Marte','Venus'],y:'Están hechos de hielo y roca.'},
{s:'¿Qué planeta sigue después de la Tierra?',o:['Marte','Venus','Júpiter'],y:'Es el cuarto planeta.'}]}
]});
T3_MUNDOS.push({name:'Lenguajes',sub:'Lectura y escritura',lead:'Trípticos, lenguas de México, poemas, teatro, mitos y leyendas: el lenguaje en todas sus formas.',temas:[
{t:'Tríptico informativo',c:'Tríptico',e:[
'Un <b>tríptico</b> es una hoja doblada en <b>tres partes</b> que informa sobre un tema de forma breve y atractiva: una campaña de salud, un museo, una feria o un tema de ciencia.',
'La <b>portada</b> lleva el título y una imagen que llame la atención. Por dentro, la información se organiza con <b>subtítulos</b>, textos cortos, listas e imágenes. La contraportada suele tener datos de contacto o una conclusión.',
'Para hacerlo bien: elige lo más importante, escribe frases cortas, usa letra legible y no amontones el texto. Un buen tríptico se entiende en un par de minutos.'],
x:['Un tríptico de la escuela sobre «Cómo prevenir el dengue» con tres secciones: qué es, síntomas y cómo evitarlo.','Los museos entregan trípticos con el mapa de las salas.'],
k:'El tríptico es una hoja doblada en tres con portada, información breve organizada y contraportada.',
q:[{s:'¿En cuántas partes se dobla un tríptico?',o:['Tres','Dos','Cinco'],y:'Tri significa tres.',p:'Tri = tres.'},
{s:'¿Qué lleva la portada de un tríptico?',o:['El título y una imagen llamativa','Todos los datos','La bibliografía completa'],y:'Debe atraer al lector.',p:'Lo primero que se ve.'},
{s:'¿Cómo deben ser los textos de un tríptico?',o:['Breves y organizados con subtítulos','Muy largos','Sin títulos'],y:'Se lee rápido.',p:'Cortos y claros.'},
{s:'¿Para qué sirve un tríptico?',o:['Para informar de forma breve y atractiva','Para contar una novela','Para escribir una carta personal'],y:'Se reparte en campañas, museos y ferias.',p:'Informa rápido.'}],
v:[{s:'Un tríptico debe tener mucho texto amontonado.',v:false,y:'Debe ser breve y fácil de leer.'},
{s:'Los subtítulos ayudan a organizar la información del tríptico.',v:true,y:'Separan cada tema.'}],
ex:[{s:'¿Cuál tema es adecuado para un tríptico informativo?',o:['Cómo prevenir el dengue','Mi poema favorito','Un chiste'],y:'Informa sobre un tema útil.'},
{s:'¿Qué parte suele tener datos de contacto?',o:['La contraportada','La portada','El título'],y:'Va al final.'}]},

{t:'Diversidad lingüística de México',c:'Diversidad lingüística',e:[
'En México se hablan muchas lenguas. Además del español, hay <b>68 lenguas indígenas</b> reconocidas, con más de 360 variantes. Entre las más habladas están el <b>náhuatl</b>, el <b>maya</b>, el <b>tseltal</b>, el <b>tsotsil</b>, el <b>mixteco</b> y el <b>zapoteco</b>. También se usa la <b>Lengua de Señas Mexicana</b>.',
'Desde 2003, la ley reconoce a las lenguas indígenas como <b>lenguas nacionales</b>, con el mismo valor que el español. Hablar una lengua indígena es un <b>derecho</b>, y nadie debe ser discriminado por ello.',
'Usamos muchas palabras de origen indígena sin darnos cuenta: del náhuatl vienen <b>chocolate</b>, <b>tomate</b>, <b>aguacate</b>, <b>chicle</b> y <b>cacahuate</b>. Cuando una lengua deja de hablarse, se pierde una forma única de ver el mundo.'],
x:['«Cacahuate» viene del náhuatl tlalcacahuatl, «cacao de la tierra».','En algunas escuelas de Chiapas las clases se dan en tsotsil y en español.'],
k:'En México se hablan 68 lenguas indígenas, que son lenguas nacionales; hablarlas es un derecho.',
q:[{s:'¿Cuántas lenguas indígenas se reconocen en México?',o:['68','5','200'],y:'Con más de 360 variantes.',p:'Más de 60.'},
{s:'¿De qué lengua vienen «chocolate» y «aguacate»?',o:['Del náhuatl','Del inglés','Del francés'],y:'Es la lengua indígena más hablada.',p:'Se hablaba en Tenochtitlan.'},
{s:'¿Qué reconoce la ley desde 2003?',o:['Que las lenguas indígenas son lenguas nacionales','Que solo se debe hablar español','Que las lenguas indígenas no existen'],y:'Tienen el mismo valor que el español.',p:'Todas valen lo mismo.'},
{s:'¿Qué se pierde cuando una lengua deja de hablarse?',o:['Una forma única de ver el mundo','Nada','Solo unas palabras'],y:'Cada lengua guarda conocimientos.',p:'Mucho más que palabras.'}],
v:[{s:'La Lengua de Señas Mexicana también es una lengua.',v:true,y:'La usan personas sordas.'},
{s:'Está bien burlarse de alguien por hablar una lengua indígena.',v:false,y:'Es discriminación; hablarla es un derecho.'}],
ex:[{s:'¿Cuál es una lengua indígena de México?',o:['Zapoteco','Portugués','Alemán'],y:'Se habla sobre todo en Oaxaca.'},
{s:'¿Cuál palabra viene del náhuatl?',o:['Tomate','Computadora','Bicicleta'],y:'Viene de tomatl.'}]},

{t:'Cuentos y poemas',c:'Cuentos y poemas',e:[
'Un <b>cuento</b> es una narración breve con pocos personajes. Tiene <b>inicio</b> (presenta personajes y lugar), <b>desarrollo</b> (aparece un problema o conflicto) y <b>desenlace</b> (se resuelve). Lo cuenta un <b>narrador</b>.',
'Un <b>poema</b> expresa sentimientos e imágenes con palabras escogidas con cuidado. Se escribe en <b>versos</b> (renglones) agrupados en <b>estrofas</b>. Muchos tienen <b>rima</b>: palabras que suenan igual al final del verso, como «canción» y «corazón».',
'Los poemas usan <b>figuras</b>: la <b>comparación</b> («tus ojos son como estrellas») y la <b>personificación</b> («el viento canta en la ventana»), que da cualidades humanas a cosas o animales.'],
x:['Personificación: «La luna me sigue por el camino».','Rima: «El gato se fue al tejado / y miró el cielo nublado».'],
k:'El cuento tiene inicio, desarrollo y desenlace; el poema usa versos, estrofas, rima y figuras.',
q:[{s:'¿En qué parte del cuento aparece el problema?',o:['En el desarrollo','En el inicio','En el título'],y:'Ahí ocurre el conflicto.',p:'La parte de en medio.'},
{s:'¿Cómo se llaman los renglones de un poema?',o:['Versos','Párrafos','Capítulos'],y:'Se agrupan en estrofas.',p:'Empieza con v.'},
{s:'«El viento canta en la ventana.» ¿Qué figura es?',o:['Personificación','Comparación','Rima'],y:'El viento no canta: se le da una acción humana.',p:'Algo que hace una persona.'},
{s:'¿Qué palabras riman?',o:['Canción y corazón','Mesa y sol','Árbol y río'],y:'Terminan con el mismo sonido.',p:'Suenan igual al final.'}],
v:[{s:'El desenlace es la parte donde se resuelve el conflicto.',v:true,y:'Es el final del cuento.'},
{s:'Todos los poemas deben rimar.',v:false,y:'Hay poemas sin rima, llamados de verso libre.'}],
ex:[{s:'«Sus ojos brillan como estrellas.» ¿Qué figura es?',o:['Comparación','Personificación','Narrador'],y:'Usa «como» para comparar.'},
{s:'¿Cómo se llama un grupo de versos?',o:['Estrofa','Capítulo','Escena'],y:'Un poema puede tener varias estrofas.'}]},

{t:'Guiones teatrales',c:'Guiones teatrales',e:[
'Un <b>guion teatral</b> es el texto que se usa para representar una obra. No tiene narrador: la historia avanza con lo que dicen los personajes, llamados <b>diálogos</b>.',
'Antes de cada diálogo va el <b>nombre del personaje</b>. Las <b>acotaciones</b> son indicaciones entre paréntesis que dicen cómo se mueve, cómo habla o qué hay en el escenario: «(entra corriendo, asustado)».',
'La obra se divide en <b>actos</b> y <b>escenas</b>. Una escena cambia cuando entra o sale un personaje o cambia el lugar. Al principio suele haber una lista de <b>personajes</b>.'],
x:['LUCÍA: (mirando por la ventana) ¡Ya llegó la tormenta!','PEDRO: (en voz baja) No hagas ruido, alguien viene.'],
k:'El guion teatral tiene personajes, diálogos y acotaciones entre paréntesis, y se divide en actos y escenas.',
q:[{s:'¿Qué son las acotaciones?',o:['Indicaciones de cómo actuar, entre paréntesis','Los nombres de los actores','El final de la obra'],y:'Ayudan a representar la obra.',p:'Van entre paréntesis.'},
{s:'¿Qué va antes de cada diálogo?',o:['El nombre del personaje','Un número','Un dibujo'],y:'Así se sabe quién habla.',p:'Quién habla.'},
{s:'¿Cómo avanza la historia en el teatro?',o:['Con los diálogos de los personajes','Con un narrador','Con imágenes'],y:'No hay narrador.',p:'Lo que dicen los personajes.'},
{s:'¿Cuándo cambia una escena?',o:['Cuando entra o sale un personaje o cambia el lugar','Cada vez que alguien habla','Nunca'],y:'Marca una nueva parte de la obra.',p:'Entradas, salidas o lugar.'}],
v:[{s:'Un guion teatral tiene un narrador que cuenta todo.',v:false,y:'La historia avanza con los diálogos.'},
{s:'«(entra corriendo)» es una acotación.',v:true,y:'Indica una acción.'}],
ex:[{s:'«LUCÍA: (triste) Perdí mi cuaderno.» ¿Qué parte es «(triste)»?',o:['Una acotación','El nombre del personaje','Un acto'],y:'Indica cómo habla.'},
{s:'¿En qué se divide una obra de teatro?',o:['En actos y escenas','En capítulos y versos','En estrofas'],y:'Así se organiza la representación.'}]},

{t:'Mitos y leyendas',c:'Mitos y leyendas',e:[
'Los <b>mitos</b> son relatos antiguos que explican el <b>origen</b> del mundo, de los seres humanos o de fenómenos naturales. Sus personajes suelen ser <b>dioses</b> y seres sobrenaturales.',
'Las <b>leyendas</b> cuentan sucesos con un <b>fondo real</b> (un lugar, una época o un personaje que existió) mezclados con elementos fantásticos. Se ubican en lugares que conocemos.',
'Ambos se transmitieron de forma <b>oral</b>, de generación en generación, por eso tienen varias versiones. Son parte de la <b>identidad</b> de los pueblos.'],
x:['Mito: en la tradición mexica, Quetzalcóatl bajó al inframundo por los huesos de los antiguos seres humanos para crear una nueva humanidad.','Leyenda: la de la Llorona se cuenta en muchas ciudades de México, cada una con su versión.'],
k:'Los mitos explican orígenes con dioses; las leyendas mezclan hechos y lugares reales con fantasía.',
q:[{s:'¿Qué explican los mitos?',o:['El origen del mundo y de los fenómenos naturales','Las noticias del día','Cómo hacer una receta'],y:'Son relatos de origen.',p:'¿Cómo empezó todo?'},
{s:'¿Qué personajes aparecen en los mitos?',o:['Dioses y seres sobrenaturales','Solo animales reales','Presidentes'],y:'Por eso explican lo que parecía misterioso.',p:'Seres con poderes.'},
{s:'¿Qué tienen las leyendas?',o:['Un fondo real mezclado con fantasía','Solo hechos comprobados','Solo dioses'],y:'Se ubican en lugares conocidos.',p:'Algo real y algo fantástico.'},
{s:'¿Cómo se transmitían los mitos y las leyendas?',o:['De forma oral, de generación en generación','Por internet','Por la radio'],y:'Por eso tienen varias versiones.',p:'De boca en boca.'}],
v:[{s:'La Llorona es una leyenda.',v:true,y:'Mezcla lugares reales con un personaje fantástico.'},
{s:'Los mitos y las leyendas tienen una sola versión.',v:false,y:'Al contarse de boca en boca, cambian.'}],
ex:[{s:'Un relato explica cómo los dioses crearon el Sol y la Luna. ¿Qué es?',o:['Un mito','Una leyenda','Una noticia'],y:'Explica un origen con dioses.'},
{s:'¿Por qué son importantes los mitos y las leyendas?',o:['Son parte de la identidad de los pueblos','Porque son noticias','Porque son reglas'],y:'Guardan su historia y sus valores.'}]}
]});
T3_MUNDOS.push({name:'Matemáticas',sub:'Pensamiento matemático',lead:'Croquis, medidas grandes, áreas, gráficas y probabilidad: matemáticas para entender el mundo.',temas:[
{t:'Croquis: ubicar personas, objetos y lugares',c:'Croquis',e:[
'Un <b>croquis</b> es un dibujo sencillo de un lugar visto desde arriba. No tiene que ser perfecto: sirve para <b>ubicar</b> lugares y explicar cómo llegar.',
'Incluye <b>puntos de referencia</b> (lugares fáciles de reconocer, como una iglesia o una tienda), los nombres de las calles y, si se puede, una flecha que indique el <b>norte</b>.',
'Para dar indicaciones se usan expresiones como «camina dos calles hacia el norte», «da vuelta a la derecha», «está enfrente de», «a un lado de», «en la esquina de».'],
x:['«La papelería está en la esquina de Hidalgo y Morelos, enfrente del parque.»','En un croquis de la escuela se marcan los salones, la dirección, los baños y la salida de emergencia.'],
k:'El croquis es un dibujo visto desde arriba con puntos de referencia, calles y el norte.',
q:[{s:'¿Qué es un croquis?',o:['Un dibujo sencillo de un lugar visto desde arriba','Una fotografía','Una gráfica de barras'],y:'Sirve para ubicar lugares.',p:'Un dibujo para orientarse.'},
{s:'¿Qué es un punto de referencia?',o:['Un lugar fácil de reconocer','Un número de teléfono','Un punto en una gráfica'],y:'Ayuda a orientarse.',p:'Algo que todos conocen.'},
{s:'¿Qué indica la flecha con una N en un croquis?',o:['El norte','La salida','El nombre del autor'],y:'Ayuda a orientar el dibujo.',p:'Un punto cardinal.'},
{s:'¿Cuál es una buena indicación?',o:['Camina dos calles al norte y da vuelta a la derecha.','Ve por allá.','Está cerca.'],y:'Es precisa.',p:'La más precisa.'}],
v:[{s:'Un croquis debe ser un dibujo perfecto y a escala exacta.',v:false,y:'Es un dibujo sencillo; lo importante es que se entienda.'},
{s:'Los nombres de las calles ayudan en un croquis.',v:true,y:'Permiten dar indicaciones precisas.'}],
ex:[{s:'Si caminas hacia el norte y das vuelta a la derecha, ¿hacia dónde vas?',o:['Al este','Al oeste','Al sur'],y:'Mirando al norte, la derecha es el este.'},
{s:'¿Desde dónde se dibuja un croquis?',o:['Como si se viera desde arriba','De frente','Desde abajo'],y:'Como un mapa.'}]},

{t:'Kilómetros y toneladas',c:'Kilómetros y toneladas',e:[
'Para medir <b>distancias grandes</b> usamos el <b>kilómetro</b> (km): <b>1 km = 1 000 metros</b>. La distancia entre ciudades o la longitud de un río se miden en kilómetros.',
'Para medir <b>masas grandes</b> usamos la <b>tonelada</b> (t): <b>1 t = 1 000 kilogramos</b>. Un coche pesa más o menos una tonelada y un elefante, varias.',
'Para convertir: de km a m, multiplica por 1 000 (3 km = 3 000 m); de m a km, divide entre 1 000 (2 500 m = 2.5 km). Igual con toneladas y kilogramos.'],
x:['Un maratón mide un poco más de 42 km.','Un camión que carga 8 t lleva 8 000 kg.'],
k:'1 km = 1 000 m y 1 t = 1 000 kg: se usan para distancias y masas grandes.',
q:[{s:'¿Cuántos metros tiene un kilómetro?',o:['1 000','100','10'],y:'Kilo significa mil.',p:'Kilo = mil.'},
{s:'¿Cuántos kilogramos tiene una tonelada?',o:['1 000','100','10 000'],y:'Se usa para masas grandes.',p:'Mil.'},
{s:'¿Cuántos metros son 4 km?',o:['4 000 m','400 m','40 m'],y:'4 × 1 000 = 4 000.',p:'Multiplica por mil.'},
{s:'¿Cuántos kilómetros son 2 500 m?',o:['2.5 km','25 km','250 km'],y:'2 500 ÷ 1 000 = 2.5.',p:'Divide entre mil.'}],
v:[{s:'La distancia entre dos ciudades se mide en kilómetros.',v:true,y:'Es la unidad adecuada para distancias grandes.'},
{s:'Un lápiz pesa más o menos una tonelada.',v:false,y:'Pesa unos gramos.'}],
ex:[{s:'¿Qué unidad usarías para medir la masa de una ballena?',o:['Toneladas','Gramos','Kilómetros'],y:'Una ballena pesa muchas toneladas.'},
{s:'Un camión lleva 3.5 t. ¿Cuántos kilogramos son?',o:['3 500 kg','350 kg','35 kg'],y:'3.5 × 1 000 = 3 500.'}]},

{t:'Unidades lineales y cuadradas',c:'Unidades lineales y cuadradas',e:[
'Las <b>unidades lineales</b> miden <b>longitudes</b>: el largo de una línea o el contorno de una figura. Son el centímetro (cm), el metro (m) y el kilómetro (km).',
'Las <b>unidades cuadradas</b> miden <b>superficies</b>, es decir, el <b>área</b>. Un <b>centímetro cuadrado</b> (cm²) es un cuadrado de 1 cm por lado. Un <b>metro cuadrado</b> (m²) es un cuadrado de 1 m por lado.',
'Usa unidades lineales para el perímetro (cuánto mide la orilla) y cuadradas para el área (cuánto espacio ocupa). Un salón puede tener 30 m de perímetro y 50 m² de área.'],
x:['Para poner una cerca alrededor de un jardín necesitas saber su perímetro en metros.','Para comprar pasto para el jardín necesitas saber su área en metros cuadrados.'],
k:'Unidades lineales (cm, m) miden longitudes; unidades cuadradas (cm², m²) miden áreas.',
q:[{s:'¿Qué miden las unidades cuadradas?',o:['Superficies o áreas','Longitudes','Tiempo'],y:'Por ejemplo, cm² y m².',p:'El espacio que ocupa una figura plana.'},
{s:'¿Qué es un centímetro cuadrado?',o:['Un cuadrado de 1 cm por lado','Una línea de 1 cm','Un cubo de 1 cm'],y:'Es la unidad de área pequeña.',p:'Un cuadradito.'},
{s:'Para saber cuánta cerca comprar, ¿qué necesitas?',o:['El perímetro en metros','El área en m²','El peso'],y:'La cerca va por la orilla.',p:'Va alrededor.'},
{s:'¿Cuál es una unidad cuadrada?',o:['m²','km','cm'],y:'El 2 pequeño indica «cuadrado».',p:'Tiene un 2 pequeño.'}],
v:[{s:'El área se mide en unidades cuadradas.',v:true,y:'Por ejemplo, metros cuadrados.'},
{s:'El perímetro se mide en metros cuadrados.',v:false,y:'Se mide en unidades lineales, como metros.'}],
ex:[{s:'Para comprar azulejo para un piso, ¿qué necesitas conocer?',o:['El área en m²','El perímetro en m','La altura de la pared'],y:'El azulejo cubre la superficie.'},
{s:'¿Cuántos cuadritos de 1 cm² caben en un cuadrado de 3 cm por lado?',o:['9','6','3'],y:'3 × 3 = 9.'}]},

{t:'Perímetro y área de rectángulos, paralelogramos y triángulos',c:'Perímetro y área',e:[
'El <b>perímetro</b> es la suma de todos los lados. Un rectángulo de 8 cm por 5 cm tiene un perímetro de 8 + 5 + 8 + 5 = 26 cm.',
'El <b>área del rectángulo</b> = base × altura. Ese rectángulo tiene 8 × 5 = 40 cm². El <b>paralelogramo</b> (como un rectángulo «empujado») tiene la misma fórmula: base × altura, donde la <b>altura</b> es la distancia recta entre la base y el lado de arriba, no el lado inclinado.',
'Un <b>triángulo</b> es la mitad de un rectángulo o paralelogramo con la misma base y altura. Por eso, el <b>área del triángulo</b> = (base × altura) ÷ 2. Un triángulo de base 6 cm y altura 4 cm tiene 12 cm².'],
x:['Un terreno rectangular de 20 m por 15 m tiene 300 m² de área.','Un banderín triangular de 30 cm de base y 40 cm de altura tiene 600 cm².'],
k:'Rectángulo y paralelogramo: base × altura. Triángulo: base × altura ÷ 2.',
q:[{s:'¿Cuál es el área de un rectángulo de 7 cm por 4 cm?',o:['28 cm²','22 cm²','11 cm²'],y:'7 × 4 = 28.',p:'Base por altura.'},
{s:'¿Cuál es el perímetro de un rectángulo de 7 cm por 4 cm?',o:['22 cm','28 cm','11 cm'],y:'7 + 4 + 7 + 4 = 22.',p:'Suma todos los lados.'},
{s:'¿Cuál es el área de un triángulo de base 10 cm y altura 6 cm?',o:['30 cm²','60 cm²','16 cm²'],y:'10 × 6 ÷ 2 = 30.',p:'Base por altura entre dos.'},
{s:'¿Qué altura se usa en un paralelogramo?',o:['La distancia recta entre la base y el lado de arriba','El lado inclinado','La diagonal'],y:'Forma un ángulo recto con la base.',p:'Recta, no inclinada.'}],
v:[{s:'El área de un triángulo es la mitad de la de un rectángulo con la misma base y altura.',v:true,y:'Por eso se divide entre 2.'},
{s:'El área del paralelogramo se calcula multiplicando sus dos lados inclinados.',v:false,y:'Se usa la base por la altura recta.'}],
ex:[{s:'Un terreno de 12 m por 10 m, ¿qué área tiene?',o:['120 m²','44 m²','22 m²'],y:'12 × 10 = 120.'},
{s:'Un paralelogramo tiene base 9 cm y altura 5 cm. ¿Cuál es su área?',o:['45 cm²','22.5 cm²','28 cm²'],y:'9 × 5 = 45.'}]},

{t:'Tablas, gráficas de barras y moda',c:'Gráficas y moda',e:[
'Para organizar datos usamos una <b>tabla de frecuencias</b>: en una columna van las opciones y en otra cuántas veces aparece cada una (su <b>frecuencia</b>).',
'Con la tabla se puede hacer una <b>gráfica de barras</b>: cada barra representa una opción y su altura, la frecuencia. Debe tener <b>título</b>, ejes con <b>etiquetas</b> y una escala pareja.',
'La <b>moda</b> es el dato que <b>más se repite</b>. En la lista 3, 5, 5, 7, 5, 2, la moda es 5. En una gráfica de barras, la moda es la barra más alta.'],
x:['Encuesta de fruta favorita: mango 9, plátano 5, manzana 7. La moda es mango.','En las calificaciones 8, 9, 9, 10, 7, 9, la moda es 9.'],
k:'La tabla de frecuencias organiza datos, la gráfica de barras los muestra y la moda es el dato que más se repite.',
q:[{s:'¿Qué es la moda?',o:['El dato que más se repite','El dato más grande','El promedio'],y:'Es la barra más alta en la gráfica.',p:'El que aparece más veces.'},
{s:'¿Cuál es la moda de 4, 6, 6, 8, 6, 3?',o:['6','4','8'],y:'El 6 aparece tres veces.',p:'Cuenta cuántas veces aparece cada uno.'},
{s:'¿Qué representa la altura de una barra?',o:['La frecuencia','El color','El nombre'],y:'Cuántas veces aparece la opción.',p:'Cuántas veces.'},
{s:'¿Qué debe tener una gráfica de barras?',o:['Título, ejes con etiquetas y escala pareja','Solo colores','Nada más las barras'],y:'Así se entiende.',p:'Para que se entienda.'}],
v:[{s:'En una gráfica de barras, la moda es la barra más alta.',v:true,y:'Es la opción con más frecuencia.'},
{s:'La moda siempre es el número más grande de la lista.',v:false,y:'Es el que más se repite, no el mayor.'}],
ex:[{s:'Deporte favorito: futbol 12, básquet 8, natación 5. ¿Cuál es la moda?',o:['Futbol','Básquet','Natación'],y:'Tiene la mayor frecuencia.'},
{s:'¿Qué es la frecuencia de un dato?',o:['Cuántas veces aparece','Su valor más alto','Su color'],y:'Se anota en la tabla.'}]},

{t:'Seguro, imposible o probable',c:'Probabilidad',e:[
'Algunos sucesos dependen del <b>azar</b>: no sabemos con certeza qué pasará. Los podemos clasificar en tres tipos.',
'Un suceso <b>seguro</b> siempre ocurre: al lanzar un dado normal, saldrá un número del 1 al 6. Un suceso <b>imposible</b> nunca ocurre: que salga un 7 en ese dado. Un suceso <b>probable</b> puede ocurrir o no: que salga un 4.',
'Entre los probables, unos son <b>más probables</b> que otros. Si en una bolsa hay 8 canicas rojas y 2 azules, es más probable sacar una roja.'],
x:['Que mañana salga el sol es seguro; que llueva puede ser probable.','En una ruleta con 3 partes amarillas y 1 verde, es más probable que caiga amarillo.'],
k:'Seguro siempre pasa, imposible nunca pasa y probable puede pasar; hay sucesos más probables que otros.',
q:[{s:'Al lanzar un dado normal, ¿qué tipo de suceso es sacar un 8?',o:['Imposible','Seguro','Probable'],y:'El dado solo tiene del 1 al 6.',p:'¿El dado tiene un 8?'},
{s:'Al lanzar una moneda, ¿qué tipo de suceso es que caiga águila?',o:['Probable','Seguro','Imposible'],y:'Puede caer águila o sol.',p:'Puede pasar o no.'},
{s:'Hay 9 canicas rojas y 1 azul. ¿Qué es más probable sacar?',o:['Una roja','Una azul','Las dos igual'],y:'Hay muchas más rojas.',p:'¿De cuál hay más?'},
{s:'¿Cuál suceso es seguro?',o:['Que un dado normal caiga en un número del 1 al 6','Que llueva mañana','Que ganes la lotería'],y:'Siempre ocurre.',p:'Siempre pasa.'}],
v:[{s:'Un suceso probable siempre ocurre.',v:false,y:'Puede ocurrir o no.'},
{s:'En una bolsa solo con canicas azules, sacar una azul es seguro.',v:true,y:'No hay otra opción.'}],
ex:[{s:'En una bolsa hay 5 canicas verdes y 5 amarillas. ¿Qué es más probable?',o:['Las dos igual','Verde','Amarilla'],y:'Hay la misma cantidad.'},
{s:'¿Qué tipo de suceso es que una piedra soltada en el aire suba sola al cielo?',o:['Imposible','Seguro','Probable'],y:'La gravedad la hace caer.'}]}
]});
T3_MUNDOS.push({name:'Geografía',sub:'Ética, naturaleza y sociedades',lead:'Pueblos originarios, comunidades afromexicanas, culturas del mundo y personas que migran.',temas:[
{t:'Pueblos originarios y afromexicanos',c:'Pueblos originarios y afromexicanos',e:[
'Los <b>pueblos originarios</b> o indígenas descienden de quienes ya vivían en este territorio antes de la llegada de los europeos. Hoy hay más de <b>60 pueblos indígenas</b> en México, como los nahuas, mayas, zapotecos, mixtecos, otomíes, tsotsiles, rarámuris y wixárikas. Conservan lenguas, formas de organización, conocimientos y fiestas propias.',
'Los <b>pueblos afromexicanos</b> descienden de personas africanas traídas a la fuerza durante la época colonial. Viven sobre todo en la <b>Costa Chica</b> de Guerrero y Oaxaca y en Veracruz. Su cultura ha aportado música, danzas como la de los diablos, y comida.',
'En <b>2019</b>, la Constitución reconoció a los pueblos afromexicanos como parte de la composición <b>pluricultural</b> de México, igual que a los pueblos indígenas. Todos tienen derecho a conservar su cultura y a no ser discriminados.'],
x:['Los rarámuris de Chihuahua son famosos por correr largas distancias en la sierra.','Gaspar Yanga, un hombre africano esclavizado, fundó en Veracruz uno de los primeros pueblos libres de América.'],
k:'México es pluricultural: pueblos indígenas y afromexicanos son parte de su identidad y tienen los mismos derechos.',
q:[{s:'¿Quiénes son los pueblos originarios?',o:['Los descendientes de quienes vivían aquí antes de los europeos','Personas que llegaron el año pasado','Solo los turistas'],y:'También se les llama pueblos indígenas.',p:'Ya estaban aquí.'},
{s:'¿Dónde vive gran parte de la población afromexicana?',o:['En la Costa Chica de Guerrero y Oaxaca','En la Antártida','Solo en la Ciudad de México'],y:'También en Veracruz.',p:'Una costa del Pacífico.'},
{s:'¿En qué año reconoció la Constitución a los pueblos afromexicanos?',o:['2019','1810','1521'],y:'Como parte de la nación pluricultural.',p:'Es muy reciente.'},
{s:'¿Qué significa que México sea pluricultural?',o:['Que tiene muchas culturas','Que tiene una sola cultura','Que no tiene cultura'],y:'Pluri significa muchas.',p:'Pluri = muchas.'}],
v:[{s:'Los pueblos indígenas conservan lenguas y conocimientos propios.',v:true,y:'Son parte del patrimonio de México.'},
{s:'Las personas afromexicanas llegaron a México por su propia voluntad.',v:false,y:'Sus antepasados fueron traídos a la fuerza durante la Colonia.'}],
ex:[{s:'¿Cuál es un pueblo indígena de México?',o:['Rarámuri','Vikingo','Celta'],y:'Vive en la sierra de Chihuahua.'},
{s:'¿Quién fundó uno de los primeros pueblos libres de América, en Veracruz?',o:['Gaspar Yanga','Hernán Cortés','Benito Juárez'],y:'Fue un hombre africano que luchó por su libertad.'}]},

{t:'Pueblos y culturas del mundo',c:'Culturas del mundo',e:[
'En el mundo viven más de 8 000 millones de personas que forman miles de pueblos y hablan alrededor de <b>7 000 lenguas</b>. Cada cultura tiene sus formas de vestir, comer, celebrar, creer y organizarse.',
'La cultura se relaciona con el lugar: los pueblos <b>inuit</b> del Ártico construyeron casas de hielo y aprovechan la foca; los pueblos del <b>desierto</b> del Sahara, como los tuareg, usan ropa amplia que protege del sol y la arena; en Japón, el arroz es la base de la comida.',
'Conocer otras culturas nos ayuda a respetar las diferencias y a darnos cuenta de que hay muchas maneras válidas de vivir. La <b>interculturalidad</b> es convivir y aprender unos de otros, en igualdad.'],
x:['El Año Nuevo chino se celebra en una fecha distinta cada año, según el calendario lunar.','En India se celebra Diwali, la fiesta de las luces.'],
k:'El mundo tiene miles de pueblos y unas 7 000 lenguas; la interculturalidad es convivir y aprender en igualdad.',
q:[{s:'¿Cuántas lenguas se hablan aproximadamente en el mundo?',o:['Unas 7 000','Unas 10','Unas 100'],y:'Muchas están en riesgo de desaparecer.',p:'Son miles.'},
{s:'¿Por qué los tuareg usan ropa amplia?',o:['Para protegerse del sol y la arena','Por moda','Porque hace frío'],y:'Viven en el desierto del Sahara.',p:'Viven en el desierto.'},
{s:'¿Qué es la interculturalidad?',o:['Convivir y aprender de otras culturas en igualdad','Imponer una sola cultura','Ignorar a otros pueblos'],y:'Respeta las diferencias.',p:'Inter = entre.'},
{s:'¿Qué relación hay entre la cultura y el lugar?',o:['La cultura se adapta al ambiente donde vive el pueblo','Ninguna','Todas las culturas son iguales en todo lugar'],y:'Por ejemplo, la ropa y la vivienda.',p:'Piensa en el clima.'}],
v:[{s:'Todas las culturas del mundo celebran las mismas fiestas.',v:false,y:'Cada cultura tiene sus propias celebraciones.'},
{s:'Conocer otras culturas ayuda a respetar las diferencias.',v:true,y:'Descubrimos otras formas de vivir.'}],
ex:[{s:'¿Qué pueblo vive en el Ártico?',o:['Los inuit','Los tuareg','Los mayas'],y:'Se adaptaron al frío extremo.'},
{s:'¿Qué fiesta se celebra en India?',o:['Diwali, la fiesta de las luces','El Día de Muertos','La Guelaguetza'],y:'Es una de sus fiestas más importantes.'}]},

{t:'Migración y derechos humanos',c:'Migración',e:[
'<b>Migrar</b> es cambiar de lugar de residencia. Quien sale de su país <b>emigra</b> y quien llega a otro país <b>inmigra</b>. También hay migración dentro del mismo país, por ejemplo del campo a la ciudad.',
'Las personas migran por muchas razones: buscar <b>trabajo</b>, estudiar, reunirse con su familia, huir de la <b>violencia</b> o de <b>desastres</b>. México es un país de origen, de tránsito y de destino de migrantes.',
'Muchas personas migrantes envían dinero a sus familias, llamado <b>remesas</b>. Todas las personas migrantes tienen <b>derechos humanos</b>, sin importar si tienen papeles o no: derecho a la salud, a la seguridad, a un trato digno y a no ser discriminadas.'],
x:['Una familia de Michoacán emigra a Estados Unidos para trabajar y envía remesas a sus abuelos.','Personas de Centroamérica cruzan México para llegar al norte: México es país de tránsito.'],
k:'Migrar es cambiar de lugar de residencia; las personas migrantes tienen derechos humanos siempre.',
q:[{s:'¿Qué significa emigrar?',o:['Salir de tu país para vivir en otro','Llegar a vivir a un país','Ir de vacaciones'],y:'E- de salir.',p:'E- = salir.'},
{s:'¿Cuál es una causa de la migración?',o:['Buscar trabajo','Querer ver la televisión','Cambiar de peinado'],y:'También huir de la violencia o reunirse con la familia.',p:'Razones importantes de vida.'},
{s:'¿Qué son las remesas?',o:['Dinero que los migrantes envían a sus familias','Un tipo de pasaporte','Una frontera'],y:'Son muy importantes para muchas familias.',p:'Dinero que se manda.'},
{s:'¿Las personas migrantes sin papeles tienen derechos humanos?',o:['Sí, siempre','No','Solo algunos días'],y:'Los derechos humanos son de todas las personas.',p:'Son humanos.'}],
v:[{s:'México es país de origen, tránsito y destino de migrantes.',v:true,y:'Salen, cruzan y llegan personas.'},
{s:'Migrar del campo a la ciudad no es migración.',v:false,y:'Es migración interna, dentro del mismo país.'}],
ex:[{s:'Una persona llega a vivir a México desde Venezuela. Para México, es:',o:['Inmigrante','Emigrante','Turista'],y:'Llega a vivir al país.'},
{s:'¿Qué derecho tienen las personas migrantes?',o:['A un trato digno y a no ser discriminadas','Ninguno','Solo a trabajar sin pago'],y:'Los derechos humanos son universales.'}]}
]});
T3_MUNDOS.push({name:'Historia',sub:'La Reforma y la República',lead:'Leyes que separaron a la Iglesia del Estado, la defensa de la soberanía y el triunfo de la República.',temas:[
{t:'La Reforma y el Estado laico',c:'La Reforma',e:[
'En <b>1854</b> estalló la <b>Revolución de Ayutla</b> contra Santa Anna, que gobernaba como dictador. Al triunfar, llegó al poder un grupo de <b>liberales</b>, entre ellos <b>Benito Juárez</b>, que querían que todos fueran iguales ante la ley.',
'Los liberales aprobaron las <b>Leyes de Reforma</b> y la <b>Constitución de 1857</b>. Quitaron privilegios a la Iglesia y al ejército y, más adelante, establecieron el <b>matrimonio civil</b>, el <b>Registro Civil</b> para nacimientos y defunciones, y la <b>libertad de cultos</b>.',
'Los <b>conservadores</b> se opusieron y estalló la <b>Guerra de Reforma</b> o de Tres Años (1858-1861), que ganaron los liberales. Así nació el <b>Estado laico</b>: el gobierno no pertenece a ninguna religión y respeta que cada persona crea en lo que quiera, o en nada.'],
x:['Tu acta de nacimiento la expide el Registro Civil, una institución creada por las Leyes de Reforma.','En la escuela pública no se enseña una religión porque el Estado es laico.'],
k:'Las Leyes de Reforma separaron a la Iglesia del Estado y crearon el Registro Civil: así nació el Estado laico.',
q:[{s:'¿Qué es un Estado laico?',o:['Un gobierno que no pertenece a ninguna religión y respeta todas las creencias','Un gobierno de sacerdotes','Un gobierno sin leyes'],y:'Cada persona elige su creencia.',p:'Separado de las religiones.'},
{s:'¿Qué institución crearon las Leyes de Reforma?',o:['El Registro Civil','El Banco de México','La UNAM'],y:'Registra nacimientos, matrimonios y defunciones.',p:'Expide tu acta de nacimiento.'},
{s:'¿Quiénes impulsaron las Leyes de Reforma?',o:['Los liberales, como Benito Juárez','Los conservadores','Los franceses'],y:'Buscaban la igualdad ante la ley.',p:'El grupo de Juárez.'},
{s:'¿Cómo se llamó la guerra entre liberales y conservadores de 1858 a 1861?',o:['Guerra de Reforma','Guerra de los Pasteles','Guerra de Independencia'],y:'También se llama Guerra de Tres Años.',p:'Lleva el nombre de las leyes.'}],
v:[{s:'La Constitución de 1857 fue impulsada por los liberales.',v:true,y:'Fue una de las bases de la Reforma.'},
{s:'En un Estado laico se prohíbe tener una religión.',v:false,y:'Se respeta la libertad de creer o no creer.'}],
ex:[{s:'¿Contra quién fue la Revolución de Ayutla?',o:['Contra Santa Anna','Contra Juárez','Contra Maximiliano'],y:'Gobernaba como dictador.'},
{s:'¿Qué libertad estableció la Reforma?',o:['La libertad de cultos','La libertad de no pagar impuestos','Ninguna'],y:'Cada quien puede practicar su religión.'}]},

{t:'Defensa de la soberanía nacional',c:'Defensa de la soberanía',e:[
'La <b>soberanía</b> es el derecho de un país a gobernarse a sí mismo, sin que otro país le imponga sus decisiones. Durante la intervención francesa y el Imperio de Maximiliano, esa soberanía estuvo en peligro.',
'<b>Benito Juárez</b> no abandonó la lucha: con su gobierno republicano viajó por el país en un carruaje, hasta llegar a Paso del Norte (hoy Ciudad Juárez). Mientras, guerrilleros y generales como <b>Porfirio Díaz</b> y <b>Mariano Escobedo</b> resistían.',
'En 1866 Francia retiró su ejército por problemas en Europa. Sin ese apoyo, Maximiliano fue derrotado en <b>Querétaro</b> y fusilado en el Cerro de las Campanas en <b>1867</b>. Juárez regresó a la capital y declaró: «Entre los individuos, como entre las naciones, el respeto al derecho ajeno es la paz».'],
x:['Ciudad Juárez lleva ese nombre porque ahí se refugió el gobierno de Juárez.','La frase de Juárez sobre el respeto al derecho ajeno se sigue citando hoy.'],
k:'Juárez defendió la soberanía; en 1867 la República venció al Imperio de Maximiliano.',
q:[{s:'¿Qué es la soberanía?',o:['El derecho de un país a gobernarse a sí mismo','Un tipo de moneda','Un ejército extranjero'],y:'Nadie de fuera debe imponer sus decisiones.',p:'Gobernarse solos.'},
{s:'¿Qué hizo Juárez durante la intervención francesa?',o:['Mantuvo el gobierno republicano viajando por el país','Se rindió de inmediato','Se fue a vivir a Francia'],y:'Nunca abandonó la lucha.',p:'No se rindió.'},
{s:'¿Dónde fue derrotado Maximiliano?',o:['En Querétaro','En Yucatán','En Baja California'],y:'Fue fusilado en el Cerro de las Campanas.',p:'Una ciudad del centro.'},
{s:'¿Qué frase de Juárez se recuerda?',o:['El respeto al derecho ajeno es la paz','Tierra y libertad','Sufragio efectivo, no reelección'],y:'La dijo al regresar a la capital en 1867.',p:'Habla de respeto y paz.'}],
v:[{s:'Francia retiró su ejército de México en 1866.',v:true,y:'Por problemas en Europa.'},
{s:'Maximiliano ganó la guerra y gobernó muchos años.',v:false,y:'Fue derrotado y fusilado en 1867.'}],
ex:[{s:'¿Qué ciudad lleva el nombre de Juárez porque ahí estuvo su gobierno?',o:['Ciudad Juárez','Guadalajara','Puebla'],y:'Antes se llamaba Paso del Norte.'},
{s:'¿En qué año triunfó la República sobre el Imperio?',o:['1867','1910','1821'],y:'Con la caída de Maximiliano.'}]},

{t:'La República Restaurada',c:'República Restaurada',e:[
'Al triunfo de 1867 se le llama <b>República Restaurada</b>: se volvió a gobernar con la Constitución de 1857. Fue presidente <b>Benito Juárez</b> hasta su muerte en 1872, y después <b>Sebastián Lerdo de Tejada</b>, hasta 1876.',
'El gobierno quiso <b>pacificar</b> y <b>modernizar</b> el país. Se impulsó la <b>educación</b>: en 1867 se fundó la <b>Escuela Nacional Preparatoria</b>, y se promovió la primaria gratuita y obligatoria. En 1873 se inauguró el <b>ferrocarril</b> entre la Ciudad de México y Veracruz.',
'Pero seguía habiendo problemas: rebeliones, pobreza en el campo y caminos inseguros. En 1876 <b>Porfirio Díaz</b> se levantó en armas contra Lerdo y tomó el poder. Así empezó una nueva etapa, el Porfiriato.'],
x:['El tren México-Veracruz redujo un viaje de varios días a menos de un día.','La Escuela Nacional Preparatoria sigue existiendo como parte de la UNAM.'],
k:'De 1867 a 1876 se restauró la República con Juárez y Lerdo: se impulsaron la educación y el ferrocarril.',
q:[{s:'¿Qué constitución se usó en la República Restaurada?',o:['La de 1857','La de 1917','La de Apatzingán'],y:'Se volvió a aplicar tras vencer al Imperio.',p:'La de la Reforma.'},
{s:'¿Qué ferrocarril se inauguró en 1873?',o:['El de la Ciudad de México a Veracruz','El de Tijuana a Cancún','El Tren Maya'],y:'Conectó la capital con el principal puerto.',p:'Llegaba al puerto más importante.'},
{s:'¿Quién gobernó después de la muerte de Juárez?',o:['Sebastián Lerdo de Tejada','Maximiliano','Agustín de Iturbide'],y:'Gobernó hasta 1876.',p:'Un liberal que trabajó con Juárez.'},
{s:'¿Qué escuela se fundó en 1867?',o:['La Escuela Nacional Preparatoria','La primera universidad de América','El Colegio Militar'],y:'Hoy es parte de la UNAM.',p:'Se cursa antes de la universidad.'}],
v:[{s:'Durante la República Restaurada se impulsó la educación.',v:true,y:'Se promovió la primaria gratuita y obligatoria.'},
{s:'La República Restaurada terminó con la llegada de Maximiliano.',v:false,y:'Terminó en 1876, cuando Porfirio Díaz tomó el poder.'}],
ex:[{s:'¿Qué buscaba el gobierno de la República Restaurada?',o:['Pacificar y modernizar el país','Volver a ser colonia','Eliminar las escuelas'],y:'Después de muchos años de guerra.'},
{s:'¿Quién tomó el poder en 1876?',o:['Porfirio Díaz','Benito Juárez','Vicente Guerrero'],y:'Así comenzó el Porfiriato.'}]}
]});
T3_MUNDOS.push({name:'Civismo',sub:'Formación cívica y ética',lead:'Tu integridad, tus derechos humanos y cómo reconocer y frenar la discriminación.',temas:[
{t:'Protección de la integridad',c:'Protección de la integridad',e:[
'La <b>integridad personal</b> es tu derecho a que nadie dañe tu cuerpo, tus emociones ni tu dignidad. Incluye estar a salvo de golpes, insultos, humillaciones, acoso y abuso, en casa, en la escuela y en internet.',
'Para protegerla ayudan algunas acciones: identificar a tus <b>adultos de confianza</b>, conocer tus <b>límites</b> y decirlos con firmeza, no compartir datos personales ni fotos con desconocidos, y pedir ayuda cuando algo te incomoda o te da miedo.',
'Las autoridades también deben protegerte. En México existen el <b>DIF</b>, las <b>Procuradurías de Protección de Niñas, Niños y Adolescentes</b> y el número de emergencias <b>911</b>. La Ley General de los Derechos de Niñas, Niños y Adolescentes reconoce tu derecho a vivir una vida libre de violencia.'],
x:['Si alguien en un juego en línea te pide tu dirección, no la des y avisa a un adulto.','Si un compañero sufre acoso escolar, contarlo a una maestra es una forma de protegerlo.'],
k:'Tienes derecho a que nadie dañe tu cuerpo ni tu dignidad; protégete con tus límites, tus adultos de confianza y pidiendo ayuda.',
q:[{s:'¿Qué es la integridad personal?',o:['Tu derecho a que nadie dañe tu cuerpo, emociones ni dignidad','Tu calificación en la escuela','Tu ropa favorita'],y:'Es un derecho humano.',p:'Que nadie te dañe.'},
{s:'Alguien en línea te pide tu dirección. ¿Qué haces?',o:['No la doy y aviso a un adulto','Se la doy','Le mando una foto de mi casa'],y:'Tus datos son privados.',p:'Protege tus datos.'},
{s:'¿Qué institución protege a niñas y niños en México?',o:['El DIF','Un centro comercial','Un equipo de futbol'],y:'También las Procuradurías de Protección.',p:'Desarrollo Integral de la Familia.'},
{s:'¿Qué es un límite personal?',o:['Lo que aceptas y lo que no en cómo te tratan','Una línea en la cancha','Un número de teléfono'],y:'Puedes decirlo con firmeza.',p:'Lo que no permites.'}],
v:[{s:'La integridad personal también se protege en internet.',v:true,y:'El acoso digital también daña.'},
{s:'Si te da miedo algo, es mejor no contarlo a nadie.',v:false,y:'Pedir ayuda a un adulto de confianza es lo correcto.'}],
ex:[{s:'¿Qué ley reconoce tu derecho a vivir libre de violencia?',o:['La Ley General de los Derechos de Niñas, Niños y Adolescentes','La ley de tránsito','El reglamento del salón'],y:'Protege a menores de 18 años.'},
{s:'Un compañero sufre acoso escolar. ¿Qué puedes hacer?',o:['Contarlo a una maestra','Unirte a las burlas','Ignorarlo'],y:'Así ayudas a protegerlo.'}]},

{t:'Derechos humanos',c:'Derechos humanos',e:[
'Los <b>derechos humanos</b> son las condiciones que toda persona necesita para vivir con <b>dignidad</b>: el derecho a la vida, a la salud, a la educación, a la alimentación, a la libertad de expresión, a una vivienda y a un trato igual.',
'Son <b>universales</b> (de todas las personas, sin importar dónde nacieron), <b>inalienables</b> (nadie te los puede quitar), <b>indivisibles</b> e <b>interdependientes</b> (todos son igual de importantes y se relacionan). En 1948 se proclamó la <b>Declaración Universal de los Derechos Humanos</b>.',
'En México, el <b>artículo 1.º</b> de la Constitución obliga a todas las autoridades a respetarlos. La <b>Comisión Nacional de los Derechos Humanos</b> (CNDH) recibe quejas cuando una autoridad los viola. Las niñas y los niños tienen además derechos especiales, como jugar y ser escuchados.'],
x:['El derecho a la educación se cumple cuando una niña puede ir a la escuela sin pagar.','Si una autoridad maltrata a una persona detenida, se puede presentar una queja ante la CNDH.'],
k:'Los derechos humanos son universales e inalienables; el artículo 1.º obliga a las autoridades a respetarlos.',
q:[{s:'¿Qué significa que los derechos humanos sean universales?',o:['Que son de todas las personas','Que solo son de algunos países','Que se compran'],y:'Sin importar dónde naciste.',p:'Universal = de todos.'},
{s:'¿Qué significa inalienables?',o:['Que nadie te los puede quitar','Que vienen del espacio','Que caducan'],y:'Los tienes siempre.',p:'No se pueden quitar.'},
{s:'¿Qué artículo de la Constitución obliga a respetar los derechos humanos?',o:['El artículo 1.º','El artículo 115','El artículo 50'],y:'Es el primero de la Constitución.',p:'El primero.'},
{s:'¿Qué institución recibe quejas cuando una autoridad viola los derechos humanos?',o:['La CNDH','La FIFA','El cine'],y:'Comisión Nacional de los Derechos Humanos.',p:'Comisión Nacional…'}],
v:[{s:'La Declaración Universal de los Derechos Humanos se proclamó en 1948.',v:true,y:'Después de la Segunda Guerra Mundial.'},
{s:'Algunos derechos humanos son más importantes que otros.',v:false,y:'Son indivisibles: todos importan por igual.'}],
ex:[{s:'¿Cuál es un derecho humano?',o:['La educación','Tener un celular de lujo','Ganar siempre'],y:'Es necesario para vivir con dignidad.'},
{s:'¿Qué derecho especial tienen las niñas y los niños?',o:['Jugar y ser escuchados','Votar en elecciones','Manejar autos'],y:'Lo reconoce la Convención sobre los Derechos del Niño.'}]},

{t:'Discriminación: reconocerla y frenarla',c:'Discriminación',e:[
'<b>Discriminar</b> es tratar a alguien peor, excluirlo o negarle un derecho por alguna característica: su origen, su color de piel, su lengua, su género, su religión, una discapacidad, su forma de vestir o su situación económica.',
'La discriminación muchas veces empieza con <b>prejuicios</b> (opiniones sin conocer a la persona) y <b>estereotipos</b> (ideas fijas sobre un grupo, como «todos los de tal lugar son…»). Se nota en burlas, apodos, exclusión de juegos o negar un servicio.',
'Para frenarla: no participar en burlas, apoyar a quien es discriminado, cuestionar los estereotipos y avisar a un adulto. En México, el <b>CONAPRED</b> (Consejo Nacional para Prevenir la Discriminación) y el artículo 1.º de la Constitución prohíben la discriminación.'],
x:['No dejar jugar a un niño porque usa silla de ruedas es discriminación; adaptar el juego para que participe es inclusión.','Burlarse del acento de una compañera que habla mixteco es discriminación.'],
k:'Discriminar es tratar peor a alguien por una característica; se frena sin burlas, apoyando y cuestionando estereotipos.',
q:[{s:'¿Qué es discriminar?',o:['Tratar peor a alguien por una característica','Ayudar a un compañero','Compartir el almuerzo'],y:'Le niega igualdad.',p:'Trato injusto.'},
{s:'¿Qué es un prejuicio?',o:['Una opinión sobre alguien sin conocerlo','Un dato comprobado','Un juego'],y:'Pre-juicio: juzgar antes.',p:'Juzgar antes de conocer.'},
{s:'¿Cuál acción frena la discriminación?',o:['Apoyar a quien es discriminado','Reírse de las burlas','Excluir a quien es diferente'],y:'Muestra solidaridad.',p:'Ponerte de su lado.'},
{s:'¿Qué institución trabaja para prevenir la discriminación en México?',o:['El CONAPRED','El SAT','La NASA'],y:'Consejo Nacional para Prevenir la Discriminación.',p:'Consejo Nacional para Prevenir…'}],
v:[{s:'Burlarse del acento de alguien que habla una lengua indígena es discriminación.',v:true,y:'Se le trata peor por su lengua.'},
{s:'Los estereotipos describen bien a todas las personas de un grupo.',v:false,y:'Son ideas fijas que no toman en cuenta a cada persona.'}],
ex:[{s:'Adaptar un juego para que participe un compañero en silla de ruedas es:',o:['Inclusión','Discriminación','Exclusión'],y:'Todos pueden participar.'},
{s:'«Todas las niñas son malas para las matemáticas» es un:',o:['Estereotipo','Dato científico','Derecho'],y:'Es una idea falsa sobre un grupo.'}]}
]});
